<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<title>2048</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    color-scheme: dark;
    --gap: 10px;
    --board: max(280px, min(460px, calc(100vw - 36px), calc(100vh - 230px)));
    --cell: calc((var(--board) - 5 * var(--gap)) / 4);
    --tile-radius: 8px;
    --gold: #f2b53d;
    --text: #e8ecf3;
    --muted: #8b95a6;
    --panel: #1a2029;
    --panel-edge: #27303e;
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
    background-color: #0d1117;
    background-image: radial-gradient(1100px 700px at 50% -120px, #1e2937 0%, rgba(13, 17, 23, 0) 65%);
    background-repeat: no-repeat;
    color: var(--text);
    min-height: 100vh;
    display: flex;
    justify-content: center;
    padding: 20px 16px 28px;
    -webkit-font-smoothing: antialiased;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
  }

  .wrap {
    width: var(--board);
    margin: auto;
    display: flex;
    flex-direction: column;
    gap: 14px;
    animation: fadeUp .5s cubic-bezier(.2, .7, .3, 1) both;
  }
  @keyframes fadeUp { from { opacity: 0; transform: translateY(12px); } }

  /* ---------- header ---------- */
  .top { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; flex-wrap: wrap; }
  h1 {
    font-size: 44px; line-height: 1; font-weight: 800; letter-spacing: -1.5px;
    color: var(--gold);
    background: linear-gradient(180deg, #ffd76e 10%, #e9a63a 90%);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .tagline { color: var(--muted); font-size: 13px; margin-top: 6px; }
  .tagline strong { color: #c9d2e0; font-weight: 700; }

  .scores { display: flex; gap: 8px; }
  .scorebox {
    position: relative;
    background: var(--panel);
    border: 1px solid var(--panel-edge);
    border-radius: 10px;
    padding: 7px 14px 8px;
    min-width: 84px;
    text-align: center;
  }
  .scorebox .label {
    display: block; font-size: 10px; font-weight: 700; letter-spacing: 1.6px;
    text-transform: uppercase; color: var(--muted);
  }
  .scorebox .val {
    display: block; font-size: 22px; font-weight: 800; margin-top: 1px;
    font-variant-numeric: tabular-nums; color: #fff;
  }
  #score.bump { animation: bump 220ms ease; }
  @keyframes bump { 40% { transform: scale(1.25); color: #ffd97a; } }
  .score-add {
    position: absolute; left: 0; right: 0; top: 2px;
    font-size: 17px; font-weight: 800; color: var(--gold);
    pointer-events: none; animation: rise 800ms ease-out forwards;
  }
  @keyframes rise { to { opacity: 0; transform: translateY(-30px); } }

  /* ---------- subline ---------- */
  .subline { display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; }
  .hint { color: var(--muted); font-size: 13.5px; line-height: 1.45; max-width: 34ch; }

  .btn {
    appearance: none; border: none; cursor: pointer; font: inherit;
    font-weight: 800; font-size: 14px; letter-spacing: .3px;
    color: #2b1d04;
    background: linear-gradient(180deg, #f8c74d, #e9a232);
    padding: 10px 18px; border-radius: 10px;
    box-shadow: 0 3px 0 #b97f1d, 0 8px 18px rgba(0, 0, 0, .35);
    transition: filter .15s ease, transform .06s ease, box-shadow .06s ease;
  }
  .btn:hover { filter: brightness(1.08); }
  .btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #b97f1d, 0 4px 10px rgba(0, 0, 0, .3); }
  button:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

  /* ---------- board ---------- */
  .board-wrap { position: relative; }
  #board {
    position: relative;
    width: var(--board); height: var(--board);
    background: #171c24;
    border-radius: 14px;
    box-shadow: 0 0 0 1px var(--panel-edge), 0 24px 48px -20px rgba(0, 0, 0, .8);
    touch-action: none;
  }
  .cell, .tile {
    position: absolute; left: 0; top: 0;
    width: var(--cell); height: var(--cell);
    transform: translate(
      calc(var(--gap) + var(--x) * (var(--cell) + var(--gap))),
      calc(var(--gap) + var(--y) * (var(--cell) + var(--gap)))
    );
  }
  .cell { border-radius: var(--tile-radius); background: #232b37; }

  .tile {
    z-index: 2;
    transition: transform 130ms cubic-bezier(.22, .61, .36, 1);
    will-change: transform;
  }
  .tile .inner {
    width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
    border-radius: var(--tile-radius);
    font-weight: 800; letter-spacing: -.02em;
    font-variant-numeric: tabular-nums;
    font-size: calc(var(--cell) * .42);
    background: var(--bg, #3a4354); color: var(--fg, #eef1f7);
    box-shadow: 0 2px 0 rgba(0, 0, 0, .18), inset 0 1px 0 rgba(255, 255, 255, .07);
  }
  .tile.d3 .inner { font-size: calc(var(--cell) * .36); }
  .tile.d4 .inner { font-size: calc(var(--cell) * .28); }
  .tile.d5 .inner { font-size: calc(var(--cell) * .23); }
  .tile.d6 .inner { font-size: calc(var(--cell) * .19); }

  .tile[data-v="2"]    .inner { --bg: #4a5468; --fg: #e9edf4; }
  .tile[data-v="4"]    .inner { --bg: #5a6884; --fg: #f0f3f9; }
  .tile[data-v="8"]    .inner { --bg: #cf8a3e; --fg: #fff7ea; }
  .tile[data-v="16"]   .inner { --bg: #d97f33; --fg: #fff5e6; }
  .tile[data-v="32"]   .inner { --bg: #e76f2e; --fg: #fff3e2; }
  .tile[data-v="64"]   .inner { --bg: #f45c26; --fg: #fff1dc; }
  .tile[data-v="128"]  .inner { --bg: #f2b53d; --fg: #4a3305; box-shadow: 0 0 20px rgba(242, 181, 61, .30), 0 2px 0 rgba(0, 0, 0, .18); }
  .tile[data-v="256"]  .inner { --bg: #f4c233; --fg: #453104; box-shadow: 0 0 24px rgba(244, 194, 51, .34), 0 2px 0 rgba(0, 0, 0, .18); }
  .tile[data-v="512"]  .inner { --bg: #f7cf2b; --fg: #403003; box-shadow: 0 0 28px rgba(247, 207, 43, .38), 0 2px 0 rgba(0, 0, 0, .18); }
  .tile[data-v="1024"] .inner { --bg: #f9da24; --fg: #3a2c02; box-shadow: 0 0 32px rgba(249, 218, 36, .42), 0 2px 0 rgba(0, 0, 0, .18); }
  .tile[data-v="2048"] .inner {
    --bg: linear-gradient(150deg, #ffd75e 0%, #ff9d2e 100%); --fg: #4a2c03;
    box-shadow: 0 0 36px rgba(255, 190, 70, .5), 0 2px 0 rgba(0, 0, 0, .18);
  }
  .tile[data-v="super"] .inner {
    --bg: linear-gradient(150deg, #9d6bff 0%, #6d3df0 100%); --fg: #ffffff;
    box-shadow: 0 0 34px rgba(140, 90, 255, .5), 0 2px 0 rgba(0, 0, 0, .18);
  }

  .tile.new .inner { animation: appear 190ms ease 100ms backwards; }
  .tile.merged .inner { animation: pop 230ms cubic-bezier(.3, 1.4, .5, 1) 80ms backwards; }
  @keyframes appear { from { transform: scale(0); opacity: 0; } }
  @keyframes pop {
    0% { transform: scale(0); opacity: .4; }
    55% { transform: scale(1.18); opacity: 1; }
    100% { transform: scale(1); }
  }

  /* ---------- overlay ---------- */
  .overlay {
    position: absolute; inset: 0; z-index: 20;
    display: flex; align-items: center; justify-content: center;
    background: rgba(13, 17, 23, .74);
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
    border-radius: 14px;
    animation: fadeIn 240ms ease;
  }
  .overlay.hidden { display: none; }
  .overlay-card { text-align: center; padding: 20px; animation: cardIn .3s cubic-bezier(.2, .9, .3, 1.2) both; }
  .overlay-card h2 { font-size: 34px; font-weight: 800; letter-spacing: -.5px; }
  .overlay-card h2.win { color: var(--gold); }
  .overlay-card p { color: var(--muted); margin: 8px 0 16px; font-size: 14px; }
  #overlay-btn { padding: 11px 26px; font-size: 15px; }
  @keyframes fadeIn { from { opacity: 0; } }
  @keyframes cardIn { from { opacity: 0; transform: scale(.85); } }

  /* ---------- footer ---------- */
  .controls { text-align: center; color: #6f7a8b; font-size: 12.5px; }
  kbd {
    display: inline-block; min-width: 22px; padding: 2px 6px; margin: 0 2px;
    background: #20262f; border: 1px solid #303a48; border-bottom-width: 2px;
    border-radius: 5px; font-family: inherit; font-size: 11.5px; color: #c6cfdd;
    text-align: center;
  }

  @media (prefers-reduced-motion: reduce) {
    .wrap, .overlay, .overlay-card, #score, .score-add { animation: none !important; }
    .tile { transition: none; }
    .tile .inner { animation: none !important; }
  }
</style>
</head>
<body>
<main class="wrap">
  <header class="top">
    <div>
      <h1>2048</h1>
      <p class="tagline">Slide, merge, and chase the <strong>2048</strong> tile.</p>
    </div>
    <div class="scores">
      <div class="scorebox">
        <span class="label">Score</span>
        <span class="val" id="score" aria-live="polite">0</span>
      </div>
      <div class="scorebox">
        <span class="label">Best</span>
        <span class="val" id="best">0</span>
      </div>
    </div>
  </header>

  <div class="subline">
    <p class="hint">Tiles with the same number merge when they collide. Every merge adds to your score.</p>
    <button class="btn" id="reset" type="button">New game</button>
  </div>

  <div class="board-wrap">
    <div id="board"></div>
    <div id="overlay" class="overlay hidden">
      <div class="overlay-card">
        <h2 id="overlay-title">Game over</h2>
        <p id="overlay-msg"></p>
        <button class="btn" id="overlay-btn" type="button">New game</button>
      </div>
    </div>
  </div>

  <p class="controls">Play with the <kbd>←</kbd><kbd>↑</kbd><kbd>↓</kbd><kbd>→</kbd> arrow keys, or swipe the board.</p>
</main>

<script>
(function () {
  'use strict';

  const SIZE = 4;
  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const overlayEl = document.getElementById('overlay');
  const overlayTitleEl = document.getElementById('overlay-title');
  const overlayMsgEl = document.getElementById('overlay-msg');
  const overlayBtnEl = document.getElementById('overlay-btn');
  const resetBtnEl = document.getElementById('reset');

  let grid = emptyGrid();   // 4x4 array of tile objects (or null)
  let score = 0;
  let best = loadBest();
  let won = false;
  let overlayMode = null;   // 'win' | 'lose' | null
  let uid = 1;

  /* ================= helpers ================= */

  function emptyGrid() {
    return Array.from({ length: SIZE }, () => Array(SIZE).fill(null));
  }

  function loadBest() {
    try { return parseInt(localStorage.getItem('best-2048'), 10) || 0; }
    catch (err) { return 0; }
  }

  function saveBest(value) {
    try { localStorage.setItem('best-2048', String(value)); } catch (err) {}
  }

  function setPos(el, r, c) {
    el.style.setProperty('--x', c);
    el.style.setProperty('--y', r);
  }

  function makeTile(value, r, c, cls) {
    const el = document.createElement('div');
    el.className = 'tile' + (cls ? ' ' + cls : '');
    el.dataset.v = value > 2048 ? 'super' : String(value);
    const digits = String(value).length;
    if (digits >= 3) el.classList.add('d' + Math.min(digits, 6));
    const inner = document.createElement('div');
    inner.className = 'inner';
    inner.textContent = value;
    el.appendChild(inner);
    setPos(el, r, c);
    boardEl.appendChild(el);
    return { value: value, r: r, c: c, el: el };
  }

  function clearTiles() {
    const tiles = boardEl.querySelectorAll('.tile');
    for (let i = 0; i < tiles.length; i++) tiles[i].remove();
  }

  function buildCells() {
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const cell = document.createElement('div');
        cell.className = 'cell';
        setPos(cell, r, c);
        boardEl.appendChild(cell);
      }
    }
  }

  /* ================= score UI ================= */

  function updateScoreUI(gained) {
    scoreEl.textContent = score;
    if (score > best) { best = score; saveBest(best); }
    bestEl.textContent = best;
    if (gained > 0) {
      scoreEl.classList.remove('bump');
      void scoreEl.offsetWidth; // restart the animation
      scoreEl.classList.add('bump');
      const add = document.createElement('span');
      add.className = 'score-add';
      add.textContent = '+' + gained;
      scoreEl.parentNode.appendChild(add);
      setTimeout(function () { add.remove(); }, 850);
    }
  }

  /* ================= core rules ================= */

  function spawnTile() {
    const empties = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (!grid[r][c]) empties.push([r, c]);
      }
    }
    if (empties.length === 0) return null;
    const spot = empties[Math.floor(Math.random() * empties.length)];
    const value = Math.random() < 0.9 ? 2 : 4;
    const tile = makeTile(value, spot[0], spot[1], 'new');
    grid[spot[0]][spot[1]] = tile;
    return tile;
  }

  // Cell of the i-th position along a line, where i = 0 is the destination end.
  function cellOf(dir, line, i) {
    switch (dir) {
      case 'left':  return [line, i];
      case 'right': return [line, SIZE - 1 - i];
      case 'up':    return [i, line];
      default:      return [SIZE - 1 - i, line]; // down
    }
  }

  function move(dir) {
    dir = typeof dir === 'string' ? dir.toLowerCase() : '';
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') return false;
    if (overlayMode === 'win') hideOverlay();

    let moved = false;
    let gained = 0;
    let reachedWin = false;
    const next = emptyGrid();
    const doomed = []; // elements of tiles consumed by a merge

    for (let line = 0; line < SIZE; line++) {
      // Gather tiles in travel order (index 0 = destination end).
      const tiles = [];
      for (let i = 0; i < SIZE; i++) {
        const pos = cellOf(dir, line, i);
        const t = grid[pos[0]][pos[1]];
        if (t) tiles.push(t);
      }

      // Pair up merges; each tile merges at most once per move.
      const slots = [];
      for (let i = 0; i < tiles.length; i++) {
        const t = tiles[i];
        const last = slots[slots.length - 1];
        if (last && !last.merged && last.tile.value === t.value) {
          last.merged = true;
          last.partner = t;
          gained += t.value * 2;
        } else {
          slots.push({ tile: t, merged: false, partner: null });
        }
      }

      // Lay the slots down from the destination end.
      for (let k = 0; k < slots.length; k++) {
        const s = slots[k];
        const pos = cellOf(dir, line, k);
        const r = pos[0], c = pos[1];
        if (s.merged) {
          const value = s.tile.value * 2;
          next[r][c] = makeTile(value, r, c, 'merged');
          setPos(s.tile.el, r, c);     // sources slide beneath the new tile
          setPos(s.partner.el, r, c);
          doomed.push(s.tile.el, s.partner.el);
          moved = true;
          if (value === 2048 && !won) { won = true; reachedWin = true; }
        } else {
          const t = s.tile;
          if (t.r !== r || t.c !== c) moved = true;
          t.r = r; t.c = c;
          next[r][c] = t;
          setPos(t.el, r, c);
        }
      }
    }

    grid = next;

    if (moved) {
      score += gained;
      updateScoreUI(gained);
      if (doomed.length) {
        setTimeout(function () { doomed.forEach(function (el) { el.remove(); }); }, 150);
      }
      spawnTile();
      if (reachedWin) showOverlay('win');
      else if (!canMove()) showOverlay('lose');
    }
    return moved;
  }

  function canMove() {
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const t = grid[r][c];
        if (!t) return true;
        if (c + 1 < SIZE && grid[r][c + 1] && grid[r][c + 1].value === t.value) return true;
        if (r + 1 < SIZE && grid[r + 1][c] && grid[r + 1][c].value === t.value) return true;
      }
    }
    return false;
  }

  /* ================= overlays ================= */

  function showOverlay(mode) {
    overlayMode = mode;
    if (mode === 'win') {
      overlayTitleEl.textContent = 'You win!';
      overlayTitleEl.classList.add('win');
      overlayMsgEl.textContent = 'You built 2048. Keep merging for a higher score.';
      overlayBtnEl.textContent = 'Keep going';
    } else {
      overlayTitleEl.textContent = 'Game over';
      overlayTitleEl.classList.remove('win');
      overlayMsgEl.textContent = 'No moves left. Final score: ' + score + '.';
      overlayBtnEl.textContent = 'New game';
    }
    overlayEl.classList.remove('hidden');
  }

  function hideOverlay() {
    overlayMode = null;
    overlayEl.classList.add('hidden');
  }

  overlayBtnEl.addEventListener('click', function () {
    if (overlayMode === 'win') hideOverlay();
    else reset();
  });

  /* ================= public API ================= */

  function reset() {
    clearTiles();
    grid = emptyGrid();
    score = 0;
    won = false;
    hideOverlay();
    updateScoreUI(0);
    spawnTile();
    spawnTile();
  }

  function setBoard(arr) {
    clearTiles();
    grid = emptyGrid();
    if (Array.isArray(arr)) {
      for (let r = 0; r < SIZE; r++) {
        const row = Array.isArray(arr[r]) ? arr[r] : [];
        for (let c = 0; c < SIZE; c++) {
          const v = Number(row[c]);
          if (v > 0) grid[r][c] = makeTile(v, r, c, 'new');
        }
      }
    }
    score = 0;
    won = false;
    hideOverlay();
    updateScoreUI(0);
  }

  function board() {
    const out = [];
    for (let r = 0; r < SIZE; r++) {
      const row = [];
      for (let c = 0; c < SIZE; c++) row.push(grid[r][c] ? grid[r][c].value : 0);
      out.push(row);
    }
    return out;
  }

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: board,
    setBoard: setBoard,
    score: function () { return score; }
  };

  /* ================= input ================= */

  resetBtnEl.addEventListener('click', reset);

  const KEYS = {
    ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down',
    a: 'left', d: 'right', w: 'up', s: 'down',
    A: 'left', D: 'right', W: 'up', S: 'down'
  };

  window.addEventListener('keydown', function (e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const dir = KEYS[e.key];
    if (!dir) return;
    e.preventDefault();
    move(dir);
  });

  let touchStart = null;
  boardEl.addEventListener('touchstart', function (e) {
    touchStart = e.changedTouches[0];
  }, { passive: true });
  boardEl.addEventListener('touchend', function (e) {
    if (!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.clientX;
    const dy = t.clientY - touchStart.clientY;
    touchStart = null;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return;
    const dir = Math.abs(dx) > Math.abs(dy)
      ? (dx > 0 ? 'right' : 'left')
      : (dy > 0 ? 'down' : 'up');
    move(dir);
  }, { passive: true });

  /* ================= boot ================= */

  buildCells();
  reset();
})();
</script>
